117	   const wall = Date.UTC(y, m - 1, d, hh!, mm!, ss); // the wall-clock reading as if it were UTC
118	   const early = offsetMinutes(new Date(wall - 86_400_000), tz);
119	   const late = offsetMinutes(new Date(wall + 86_400_000), tz);
120	   const valid = [early, late]
121	     .map((o) => wall - o * 60_000)
122	     .filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
123	   // repeated hour: two valid instants, take the earlier; gap: none valid, move forward by the gap
124	   return new Date(valid.length ? Math.min(...valid) : wall - early * 60_000);
