128	+export function formatOffset(minutes: number): string {
129	+  if (minutes === 0) return 'GMT';
130	+  const abs = Math.abs(minutes);
131	+  const rest = abs % 60 ? `:${String(abs % 60).padStart(2, '0')}` : '';
132	+  return `GMT${minutes < 0 ? '-' : '+'}${Math.floor(abs / 60)}${rest}`;
133	+}
