157	+/** ICU's own spelling of a zone, so 'Asia/Kolkata' and 'Asia/Calcutta' compare equal. */
158	+export function canonicalTimeZone(tz: string): string {
159	+  return formatter('en', tz, {}).resolvedOptions().timeZone;
160	+}
161	+
162	+/** '4:00 PM', with a plain space where ICU puts a narrow no-break one. */
163	+export function formatTime(at: Date, tz: string): string {
164	+  return formatter('en-US', tz, { hour: 'numeric', minute: '2-digit' }).format(at).replace(/\u202f/g, ' ');
165	+}
166	+
167	+/** 'Tue 27 Oct' */
168	+export function formatDate(at: Date, tz: string): string {
169	+  return formatter('en-GB', tz, { weekday: 'short', day: 'numeric', month: 'short' }).format(at);
170	+}
171	+
172	+/** 'Tue 27 Oct 2026' (en-GB would put a comma after the weekday if asked for the year too) */
173	+export function formatDateWithYear(at: Date, tz: string): string {
174	+  return `${formatDate(at, tz)} ${formatter('en-GB', tz, { year: 'numeric' }).format(at)}`;
175	+}
176	+
177	+/** A 'YYYY-MM-DD' calendar day as 'Sun 25 Oct'. */
178	+export function formatDayKey(key: string): string {
179	+  return formatDate(new Date(`${key}T12:00:00Z`), 'UTC');
180	+}
181	+
182	+/** 'BST (London)' */
183	+export function formatZone(at: Date, tz: string): string {
184	+  return `${zoneAbbreviation(at, tz)} (${cityName(tz)})`;
185	+}
186	+
187	+/** 'Tue 27 Oct, 4:00 PM BST (London)', the display style used in the UI and the emails. */
188	+export function formatWhen(at: Date, tz: string): string {
189	+  return `${formatDate(at, tz)}, ${formatTime(at, tz)} ${formatZone(at, tz)}`;
190	+}
191	+
192	+/** '4:00–5:00 PM GMT (London)'; names both zones when a clock change falls inside the span. */
193	+export function formatSpan(start: Date, end: Date, tz: string): string {
194	+  const from = formatTime(start, tz);
195	+  const to = formatTime(end, tz);
196	+  const city = cityName(tz);
197	+  if (offsetMinutes(start, tz) !== offsetMinutes(end, tz)) {
198	+    return `${from} ${zoneAbbreviation(start, tz)}–${to} ${zoneAbbreviation(end, tz)} (${city})`;
199	+  }
200	+  const samePeriod = from.slice(-2) === to.slice(-2); // 'AM' or 'PM'
201	+  return `${samePeriod ? from.slice(0, -3) : from}–${to} ${zoneAbbreviation(start, tz)} (${city})`;
202	+}
203	+
204	+/** 'London (GMT+1)', the label in the zone picker. */
205	+export function formatZoneOption(at: Date, tz: string): string {
206	+  return `${cityName(tz)} (${formatOffset(offsetMinutes(at, tz))})`;
207	+}
208	+
209	+/** The time in `tz` for a reader in `viewerTz`: '9:30 PM IST', with the date when the two sides are on different days. */
210	+export function formatOtherTime(at: Date, tz: string, viewerTz: string): string {
211	+  const time = `${formatTime(at, tz)} ${zoneAbbreviation(at, tz)}`;
212	+  return localDate(at, tz) === localDate(at, viewerTz) ? time : `${formatDate(at, tz)}, ${time}`;
213	+}
